// Narration (Piper) and rendering (FFmpeg). Paths are generated by the worker from job IDs only.
import fs from "node:fs";
import { run } from "./exec.ts";
import { probe } from "./qc.ts";

export async function synthesize(piperExe: string, voice: string, text: string, outWav: string) {
  if (!voice) throw new Error("PIPER_VOICE não configurado (caminho do modelo .onnx).");
  if (!fs.existsSync(voice)) throw new Error(`Modelo de voz Piper não encontrado: ${voice}`);
  const r = await run(piperExe, ["--model", voice, "--output_file", outWav], { input: text, timeoutMs: 180_000 });
  if (r.code !== 0 || !fs.existsSync(outWav)) throw new Error(`Piper falhou (código ${r.code}): ${r.stderr.slice(-400)}`);
}

export async function audioDuration(ffprobe: string, file: string): Promise<number> {
  const d = Number((await probe(ffprobe, file)).format?.duration);
  if (!Number.isFinite(d) || d <= 0) throw new Error("Não foi possível medir a duração do áudio.");
  return d;
}

const ts = (sec: number) => {
  const ms = Math.round(sec * 1000);
  const h = Math.floor(ms / 3_600_000), m = Math.floor((ms % 3_600_000) / 60_000), s = Math.floor((ms % 60_000) / 1000);
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")},${String(ms % 1000).padStart(3, "0")}`;
};

/** Approximate SRT: sentences timed proportionally to their length over the real audio duration. */
export function buildSrt(text: string, totalSec: number): string {
  const parts = text.split(/(?<=[.!?])\s+/).map((p) => p.trim()).filter(Boolean);
  const total = parts.reduce((a, p) => a + p.length, 0) || 1;
  let t = 0;
  return parts
    .map((p, i) => {
      const dur = (p.length / total) * totalSec;
      const line = `${i + 1}\n${ts(t)} --> ${ts(t + dur)}\n${p}\n`;
      t += dur;
      return line;
    })
    .join("\n");
}

/** Vertical 1080x1920 MP4: solid background + narration, with soft subtitle track (no filter-path escaping on Windows). */
export async function render(ffmpeg: string, input: { audio: string; srt: string; out: string; duration: number }) {
  const args = [
    "-y", "-hide_banner", "-loglevel", "error",
    "-f", "lavfi", "-i", `color=c=0x0b0f14:s=1080x1920:r=30:d=${input.duration.toFixed(2)}`,
    "-i", input.audio,
    "-i", input.srt,
    "-map", "0:v", "-map", "1:a", "-map", "2:s",
    "-c:v", "libx264", "-preset", "veryfast", "-pix_fmt", "yuv420p",
    "-c:a", "aac", "-b:a", "160k",
    "-c:s", "mov_text", "-metadata:s:s:0", "language=por",
    "-shortest", "-movflags", "+faststart",
    input.out,
  ];
  const r = await run(ffmpeg, args, { timeoutMs: 600_000 });
  if (r.code !== 0) throw new Error(`FFmpeg falhou (código ${r.code}): ${r.stderr.slice(-600)}`);
}
